// Some portions generated by Co-Pilot
"use client";

import { useTranslations } from "next-intl";
import { useRouter } from "next/navigation";
import { FiArrowRight } from "react-icons/fi";

interface ReleaseNotesVersionSelectorProps {
  availableVersions: number[];
  availableLTSVersions: number[];
}

export default function ReleaseNotesVersionSelector({
  availableVersions,
  availableLTSVersions,
}: ReleaseNotesVersionSelectorProps) {
  const tModern = useTranslations("ModernPages.release-notes");
  const router = useRouter();
  const versions = [...availableVersions].sort((a, b) => b - a);
  const groups = [
    {
      title: tModern("lts"),
      versions: versions.filter((version) =>
        availableLTSVersions.includes(version),
      ),
      lts: true,
    },
    {
      title: tModern("features"),
      versions: versions.filter(
        (version) => !availableLTSVersions.includes(version),
      ),
      lts: false,
    },
  ];

  return (
    <div className="mx-auto max-w-7xl space-y-8 px-6 py-10 sm:px-8 sm:py-12">
      {groups
        .filter((group) => group.versions.length > 0)
        .map((group) => (
          <section key={group.title}>
            <h2 className="mb-4 text-xl font-semibold">{group.title}</h2>
            <div
              className={`grid gap-3 sm:grid-cols-2 ${group.lts ? "lg:grid-cols-3" : "lg:grid-cols-4"}`}
            >
              {group.versions.map((version) => (
                <button
                  key={version}
                  type="button"
                  onClick={() => router.push(`?version=${version}`)}
                  className="group rounded-2xl border border-white/10 bg-white/[0.025] p-5 text-left transition-colors hover:border-pink/40 hover:bg-white/5 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-pink"
                >
                  <span className="mb-4 flex items-center justify-between gap-3">
                    <span className="text-2xl font-semibold tracking-tight">
                      JDK {version}
                    </span>
                    {group.lts && (
                      <span className="rounded-full border border-pink/20 bg-pink/10 px-2 py-1 text-xs text-[#ff91b7]">
                        LTS
                      </span>
                    )}
                  </span>
                  <span className="flex items-center justify-between gap-3 text-sm text-grey group-hover:text-white">
                    <span>{tModern("view")}</span>
                    <FiArrowRight
                      className="shrink-0 text-[#ff91b7]"
                      aria-hidden="true"
                    />
                  </span>
                </button>
              ))}
            </div>
          </section>
        ))}
    </div>
  );
}
